import pytest
from parse_kv import parse_kv


def test_empty_string():
    """Empty string should return empty dict."""
    assert parse_kv("") == {}


def test_single_pair():
    """Test parsing a single key-value pair."""
    assert parse_kv("key1=value1") == {"key1": "value1"}


def test_multiple_pairs():
    """Test parsing multiple key-value pairs."""
    result = parse_kv("key1=value1; key2=value2")
    assert result == {"key1": "value1", "key2": "value2"}


def test_whitespace_trimming():
    """Keys and values should be whitespace-trimmed."""
    result = parse_kv("  key1  =  value1  ;  key2  =  value2  ")
    assert result == {"key1": "value1", "key2": "value2"}


def test_escaped_semicolon():
    """Backslash-escaped semicolon should be literal semicolon in value."""
    result = parse_kv("key1=val\\;ue; key2=value2")
    assert result == {"key1": "val;ue", "key2": "value2"}


def test_value_with_escaped_semicolon():
    """Value containing escaped semicolons should preserve them."""
    result = parse_kv("message=Hello\\; World")
    assert result == {"message": "Hello; World"}


def test_multiple_escaped_semicolons():
    """Multiple escaped semicolons in value."""
    result = parse_kv("path=C:\\;Users\\;name")
    # Each \\; becomes ;, so we need to think about escaping
    assert result == {"path": "C:;Users:;name"}


def test_empty_value():
    """Empty values should work."""
    result = parse_kv("key1=; key2=value2")
    assert result == {"key1": "", "key2": "value2"}


def test_no_value_after_equals():
    """Key with no value after equals."""
    result = parse_kv("key1=; key2=value2")
    assert result["key1"] == ""


def test_trailing_semicolon():
    """Trailing semicolon should not cause issues."""
    result = parse_kv("key1=value1;")
    assert result == {"key1": "value1"}


def test_leading_semicolon():
    """Leading semicolon should not cause issues."""
    result = parse_kv(";key1=value1")
    assert result == {"key1": "value1"}


def test_consecutive_semicolons():
    """Consecutive semicolons should be handled."""
    result = parse_kv("key1=val1;;key2=val2")
    assert result == {"key1": "val1", "key2": "val2"}


def test_escaped_semicolon_at_end():
    """Escaped semicolon at end of value."""
    result = parse_kv("key1=value\\;")
    assert result == {"key1": "value;"}


def test_complex_case():
    """Complex case with multiple features."""
    result = parse_kv("  key1 = val\\;ue1  ;  key2=val2;key3=  val3  ")
    assert result == {"key1": "val;ue1", "key2": "val2", "key3": "val3"}


def test_value_equals_in_escaped():
    """Equals sign in escaped semicolon value should be preserved."""
    result = parse_kv("config=a=b\\;c=d")
    assert result == {"config": "a=b;c=d"}

